{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.design_insights_category as WITH category_base AS ( SELECT \"SKU_GROUP\" AS \"SKU_GROUP\", \"L1_CATEGORY\" AS \"L1_CATEGORY\", \"CATEGORY\" AS \"CATEGORY\", \"PRODUCT_NAME\" AS \"PRODUCT_NAME\", \"COLLAR_MAPPED\" AS \"COLLAR_MAPPED\", fit, \"PRINT_DESIGN_MAPPED\" AS \"PRINT_DESIGN_MAPPED\", \"DAYS_SINCE_LIVE\" AS \"DAYS_SINCE_LIVE\", \"ORIGINAL_PRICE\" AS \"ORIGINAL_PRICE\", sum(shopify_quant30), sum(store_quant30), sum(MP_QUANT30), SUM( ( CAST(OFFLINE_INVENTORY AS INT) + CAST(ONLINE_INVENTORY AS INT) + CAST(OFFLINE_JIT_INVENTORY AS INT) ) * COST_PRICE ) AS \"Inv Value\", SUM( ( CAST(OFFLINE_INVENTORY AS INT) + CAST(ONLINE_INVENTORY AS INT) + CAST(OFFLINE_JIT_INVENTORY AS INT) ) ) AS \"Inv count\", IFF( ( SUM(SHOPIFY_quant30) + SUM(MP_QUANT30) + SUM(STORE_QUANT30) ) = 0 AND NOT ( SUM(SHOPIFY_SALES30) + SUM(MP_sales30) + SUM(STORE_sales30) ) IS NULL, 0, ( SUM(SHOPIFY_SALES30) + SUM(MP_sales30) + SUM(STORE_sales30) ) / ( SUM(SHOPIFY_quant30) + SUM(MP_QUANT30) + SUM(STORE_QUANT30) ) ) AS \"ASP\", SUM(COST_PRICE * STORE_QUANT30) + SUM(COST_PRICE * SHOPIFY_QUANT30) + SUM(COST_PRICE * MP_QUANT30) AS \"COGS\", IFF( ( SUM(COST_PRICE * STORE_QUANT30) + SUM(COST_PRICE * SHOPIFY_QUANT30) + SUM(COST_PRICE * MP_QUANT30) ) = 0 AND NOT SUM(( OFFLINE_INVENTORY + ONLINE_INVENTORY + OFFLINE_JIT_INVENTORY ) * COST_PRICE) IS NULL, 0, SUM(( OFFLINE_INVENTORY + ONLINE_INVENTORY + OFFLINE_JIT_INVENTORY ) * COST_PRICE) / ( SUM(COST_PRICE * STORE_QUANT30) + SUM(COST_PRICE * SHOPIFY_QUANT30) + SUM(COST_PRICE * MP_QUANT30) ) ) * 30 AS \"DoI\", ( SUM(MP_SALES30) + SUM(STORE_SALES30) + SUM(SHOPIFY_SALES30) ) AS \"Sales -30d\", ( SUM(SHOPIFY_TAX30) + SUM(MP_TAX30) + SUM(STORE_TAX30) ) AS \"Tax\", ( SUM(SHOPIFY_DISCOUNT30) + SUM(STORE_DISCOUNT30) ) AS \"Discount\", SUM(( MP_QUANT30 + SHOPIFY_QUANT30 + STORE_QUANT30 )) AS \"30 Days sales quant\", IFF( SUM( SHOPIFY_QUANT30 + MP_QUANT30 + STORE_QUANT30 + ONLINE_INVENTORY + OFFLINE_INVENTORY + OFFLINE_JIT_INVENTORY ) = 0 AND NOT SUM(SHOPIFY_QUANT30 + MP_QUANT30 + STORE_QUANT30) IS NULL, 0, SUM(SHOPIFY_QUANT30 + MP_QUANT30 + STORE_QUANT30) / SUM( SHOPIFY_QUANT30 + MP_QUANT30 + STORE_QUANT30 + ONLINE_INVENTORY + OFFLINE_INVENTORY + OFFLINE_JIT_INVENTORY ) ) AS \"STR\", IFF( ( SUM(MP_SALES30) + SUM(STORE_SALES30) + SUM(SHOPIFY_SALES30) ) = 0 AND NOT ( ( SUM(MP_SALES30) + SUM(STORE_SALES30) + SUM(SHOPIFY_SALES30) ) - ( ( SUM(SHOPIFY_TAX30) + SUM(MP_TAX30) + SUM(STORE_TAX30) ) ) - SUM(COST_PRICE * MP_QUANT30) - SUM(COST_PRICE * STORE_QUANT30) - SUM(COST_PRICE * SHOPIFY_QUANT30) ) IS NULL, 0, ( ( SUM(MP_SALES30) + SUM(STORE_SALES30) + SUM(SHOPIFY_SALES30) ) - ( ( SUM(SHOPIFY_TAX30) + SUM(MP_TAX30) + SUM(STORE_TAX30) ) ) - SUM(COST_PRICE * MP_QUANT30) - SUM(COST_PRICE * STORE_QUANT30) - SUM(COST_PRICE * SHOPIFY_QUANT30) ) / ( SUM(MP_SALES30) + SUM(STORE_SALES30) + SUM(SHOPIFY_SALES30) ) ) AS \"Gross margin\", IFF( ( SUM(MP_QUANT30) + SUM(SHOPIFY_QUANT30) + SUM(STORE_QUANT30) ) = 0 AND NOT ( SUM(MARKETPLACE_RETURNS30) + SUM(SHOPIFY_RETURNS30) ) IS NULL, 0, ( SUM(MARKETPLACE_RETURNS30) + SUM(SHOPIFY_RETURNS30) ) / ( SUM(MP_QUANT30) + SUM(SHOPIFY_QUANT30) + SUM(STORE_QUANT30) ) ) * 100 AS \"Returns%\", IFF( SUM(OFFLINE_INVENTORY + ONLINE_INVENTORY + OFFLINE_JIT_INVENTORY) = 0 AND NOT SUM( CASE WHEN OVERALL_AGING >= 360 THEN OFFLINE_INVENTORY + ONLINE_INVENTORY + OFFLINE_JIT_INVENTORY ELSE 0 END ) IS NULL, 0, SUM( CASE WHEN OVERALL_AGING >= 360 THEN OFFLINE_INVENTORY + ONLINE_INVENTORY + OFFLINE_JIT_INVENTORY ELSE 0 END ) / SUM(OFFLINE_INVENTORY + ONLINE_INVENTORY + OFFLINE_JIT_INVENTORY) ) AS \"360+ Inv%\", IFF( ( SUM(MP_SALES30) + SUM(STORE_SALES30) + SUM(SHOPIFY_SALES30) + ( SUM(SHOPIFY_DISCOUNT30) + SUM(STORE_DISCOUNT30) ) ) = 0 AND NOT ( SUM(SHOPIFY_DISCOUNT30) + SUM(STORE_DISCOUNT30) ) IS NULL, 0, ( SUM(SHOPIFY_DISCOUNT30) + SUM(STORE_DISCOUNT30) ) / ( SUM(MP_SALES30) + SUM(STORE_SALES30) + SUM(SHOPIFY_SALES30) + ( SUM(SHOPIFY_DISCOUNT30) + SUM(STORE_DISCOUNT30) ) ) ) * 100 AS \"discount%\" FROM maplemonk.category_journey GROUP BY \"SKU_GROUP\", \"L1_CATEGORY\", \"CATEGORY\", \"PRODUCT_NAME\", \"COLLAR_MAPPED\", fit, \"PRINT_DESIGN_MAPPED\", \"DAYS_SINCE_LIVE\", \"ORIGINAL_PRICE\" ) SELECT cb.*, pj.\"IMAGE\" AS \"IMAGE\" FROM category_base cb LEFT JOIN maplemonk.product_journey pj ON cb.\"SKU_GROUP\" = pj.\"SKU_GROUP\";",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
